set -u
R=/scratch/jjyeung/orch_n30
date -u +%TZ
mkdir -p $R/sb_drev6; cp $R/sb_cursor_probe/AGENTS.md $R/sb_drev6/AGENTS.md
echo  | base64 -d > $R/sb_drev6/PROMPT.md
cd $R/sb_drev6 && tmux new-session -d -s sb_drev6 "OMP_NUM_THREADS=8 MKL_NUM_THREADS=8 OPENBLAS_NUM_THREADS=8 nice -n 10 timeout 7200 agent -p -f --sandbox disabled --trust --model claude-opus-5-5-xhigh 'Read PROMPT.md in this folder and carry out the task it describes, completely.' > cursor.log 2>&1"
mkdir -p $R/sb_brev4; cp $R/sb_cursor_probe/AGENTS.md $R/sb_brev4/AGENTS.md
echo  | base64 -d > $R/sb_brev4/PROMPT.md
cd $R/sb_brev4 && tmux new-session -d -s sb_brev4 "OMP_NUM_THREADS=8 MKL_NUM_THREADS=8 OPENBLAS_NUM_THREADS=8 nice -n 10 timeout 7200 agent -p -f --sandbox disabled --trust --model claude-opus-5-5-xhigh 'Read PROMPT.md in this folder and carry out the task it describes, completely.' > cursor.log 2>&1"
mkdir -p $R/sb_pfrev; cp $R/sb_cursor_probe/AGENTS.md $R/sb_pfrev/AGENTS.md
echo  | base64 -d > $R/sb_pfrev/PROMPT.md
cd $R/sb_pfrev && tmux new-session -d -s sb_pfrev "OMP_NUM_THREADS=8 MKL_NUM_THREADS=8 OPENBLAS_NUM_THREADS=8 nice -n 10 timeout 7200 agent -p -f --sandbox disabled --trust --model claude-opus-5-5-xhigh 'Read PROMPT.md in this folder and carry out the task it describes, completely.' > cursor.log 2>&1"
