cd $R/sb_rkrev && tmux new-session -d -s sb_rkrev "OMP_NUM_THREADS=8 MKL_NUM_THREADS=8 OPENBLAS_NUM_THREADS=8 nice -n 10 timeout 7200 agent -p -f --sandbox disabled --trust --model claude-opus-5-5-xhigh 'Read PROMPT.md in this folder and carry out the task it describes, completely.' > cursor.log 2>&1"
sleep 3; tmux ls -F "#{session_name}" | grep "^sb_" | tr "\n" " "
